-- BASE DE DATOS PARA TIDB CLOUD SERVERLESS — IESTP UTCUBAMBA 2026
CREATE DATABASE IF NOT EXISTS `bd_mantenimiento_iestpu` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `bd_mantenimiento_iestpu`;

CREATE TABLE usuarios (
  id INT AUTO_INCREMENT PRIMARY KEY,
  dni VARCHAR(15) NOT NULL,
  nombres VARCHAR(120) NOT NULL,
  correo VARCHAR(150) NOT NULL UNIQUE,
  clave VARCHAR(255) NOT NULL,
  rol ENUM('admin','coordinador_apsti','coordinador_cont','coordinador_enfe','coordinador_agro','tecnico') NOT NULL,
  programa VARCHAR(60) NOT NULL,
  activo TINYINT(1) NOT NULL DEFAULT 1
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE bienes_inventario (
  id INT AUTO_INCREMENT PRIMARY KEY,
  correlativo VARCHAR(10) NOT NULL,
  codigo_apsti VARCHAR(60) NOT NULL,
  codigo_interno VARCHAR(60) NOT NULL,
  denominacion VARCHAR(150) NOT NULL,
  marca VARCHAR(80) DEFAULT '-',
  modelo VARCHAR(80) DEFAULT '-',
  tipo_material VARCHAR(80) DEFAULT '-',
  color VARCHAR(60) DEFAULT '-',
  serie VARCHAR(80) DEFAULT '-',
  dimensiones VARCHAR(100) DEFAULT '-',
  especificaciones TEXT,
  programa VARCHAR(30) NOT NULL,
  area_ambiente VARCHAR(120) NOT NULL,
  responsable VARCHAR(120) DEFAULT 'Ernesto Correa Barrantes',
  fecha_compra DATE DEFAULT '2024-03-15',
  estado_conservacion VARCHAR(10) DEFAULT 'B',
  requiere_mantenimiento TINYINT(1) DEFAULT 1,
  fecha_limite_mantenimiento DATE DEFAULT '2026-11-30',
  estado_visita VARCHAR(40) DEFAULT 'Visitado',
  estado_servicio VARCHAR(40) DEFAULT 'Servicio Completo',
  fecha_viene_tecnico DATE DEFAULT '2026-11-11',
  proxima_visita DATE DEFAULT '2027-02-11',
  diagnostico TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE solicitudes_mantenimiento (
  id INT AUTO_INCREMENT PRIMARY KEY,
  codigo_solicitud VARCHAR(30) NOT NULL,
  bien_id INT NOT NULL,
  codigo_bien VARCHAR(60) NOT NULL,
  descripcion_bien VARCHAR(160) NOT NULL,
  area_solicitante VARCHAR(100) NOT NULL,
  usuario_reporta VARCHAR(120) NOT NULL,
  falla_reportada TEXT NOT NULL,
  prioridad VARCHAR(20) DEFAULT 'ALTA',
  fecha_reporte DATETIME DEFAULT CURRENT_TIMESTAMP,
  verificado_admin TINYINT(1) DEFAULT 0,
  fecha_verificacion DATETIME NULL,
  observacion_admin TEXT,
  tipo_ficha ENUM('FICHA DE OBSERVACION','FICHA DE MANTENIMIENTO') DEFAULT 'FICHA DE OBSERVACION',
  numero_ficha VARCHAR(40) NULL,
  tecnico_asignado VARCHAR(120) DEFAULT 'Téc. Carlos Quispe',
  fecha_visita_programada DATE NULL,
  diagnostico_tecnico TEXT,
  acciones_realizadas TEXT,
  estado_flujo ENUM('1_REPORTADO_AREA','2_VERIFICADO_CON_FICHA','3_ATENDIDO_AREA_TECNICA') DEFAULT '1_REPORTADO_AREA',
  resultado_servicio ENUM('PENDIENTE','SERVICIO COMPLETO') DEFAULT 'PENDIENTE',
  proxima_visita_preventiva DATE NULL,
  tipo_mantenimiento VARCHAR(30) DEFAULT 'CORRECTIVO',
  repuestos_usados TEXT NULL,
  costo_estimado DECIMAL(10,2) DEFAULT 0.00,
  horas_tecnicas DECIMAL(5,2) DEFAULT 0.00,
  foto_falla VARCHAR(255) NULL,
  foto_cierre VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS movimientos_bienes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  codigo_acta VARCHAR(40) NOT NULL,
  bien_id INT NOT NULL,
  codigo_bien VARCHAR(60) NOT NULL,
  descripcion_bien VARCHAR(160) NOT NULL,
  tipo_movimiento VARCHAR(30) NOT NULL DEFAULT 'TRASLADO',
  area_origen VARCHAR(120) NOT NULL,
  area_destino VARCHAR(120) NOT NULL,
  responsable_entrega VARCHAR(120) NOT NULL,
  responsable_recibe VARCHAR(120) NOT NULL,
  fecha_movimiento DATE NOT NULL,
  motivo TEXT NOT NULL,
  estado_movimiento VARCHAR(30) NOT NULL DEFAULT 'EJECUTADO',
  creado_en DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


CREATE TABLE IF NOT EXISTS auditoria_logs (
  id INT AUTO_INCREMENT PRIMARY KEY,
  usuario_id INT NOT NULL DEFAULT 0,
  rol VARCHAR(40) NOT NULL,
  accion VARCHAR(60) NOT NULL,
  tabla_afectada VARCHAR(60) NOT NULL,
  registro_id VARCHAR(60) NULL,
  detalle TEXT NULL,
  fecha_hora DATETIME NOT NULL,
  ip VARCHAR(64) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET FOREIGN_KEY_CHECKS = 1;
